const HIGH_ENCHANTMENT_THRESHOLD = 5;

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;

/** Applicable surcharges stack additively on the item's own base premium. */
const SURCHARGE_RATES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
  { appliesTo: isCursed, rate: 0.5 },
  { appliesTo: isHighlyEnchanted, rate: 0.3 },
];

const surchargeRateFor = (item: Item): number =>
  sumOf(SURCHARGE_RATES, ({ appliesTo, rate }) => (appliesTo(item) ? rate : 0));

/** Item-specific surcharges are levied on the affected item's own base premium. */
const surchargesFor = (item: Item): number =>
  basePremiumFor(item) * surchargeRateFor(item);
